C3 = 130.812783      # basses: written C sounds an octave lower
ORIGIN = "chiploom-recipe"
SOURCE = "ChipLoom starter bank"


def _harmonics(amplitudes: list[float], points: int = 32) -> list[float]:
    """One drawn cycle from harmonic amplitudes (sine phases), normalized to -1..1."""
    values = [sum(level * math.sin(2 * math.pi * (index + 1) * step / points)
                  for index, level in enumerate(amplitudes)) for step in range(points)]
    peak = max(map(abs, values)) or 1.0
    return [round(value / peak, 3) for value in values]


ORGAN = _harmonics([1, 0.5, 0, 0.3, 0, 0, 0, 0.15])
